CREATE OR REPLACE VIEW public.ac_canonical_invoice_rows WITH(security_invoker=true) AS WITH raw AS (SELECT i,d.payload,row_number() OVER(PARTITION BY i#>>'{customer_snapshot,customer_id}' ORDER BY i->>'created_at',i->>'invoice_id') n FROM public.crm_documents d CROSS JOIN LATERAL jsonb_array_elements(coalesce(d.payload->'invoices','[]')) i WHERE namespace='crm'), expanded AS (SELECT r.*,s.service,c.contract,coalesce((SELECT sum((l->>'amount')::numeric) FROM jsonb_array_elements(i->'lines') l WHERE CASE WHEN l->>'sku_snapshot' LIKE 'ORM-%' THEN 'ORM' WHEN l->>'sku_snapshot' LIKE 'MARCOM-%' THEN 'Marcom' ELSE i->>'service_line' END=s.service),0) base FROM raw r CROSS JOIN LATERAL (SELECT DISTINCT coalesce(i->>'service_line',CASE WHEN l->>'sku_snapshot' LIKE 'ORM-%' THEN 'ORM' WHEN l->>'sku_snapshot' LIKE 'MARCOM-%' THEN 'Marcom' END) service FROM jsonb_array_elements(i->'lines') l) s LEFT JOIN LATERAL (SELECT x contract FROM jsonb_array_elements(payload->'contracts') x WHERE x->>'contract_id'=i#>>'{contract_ids,0}' LIMIT 1) c ON true WHERE service IN ('ORM','Marcom')) SELECT md5(i#>>'{customer_snapshot,customer_id}')::uuid customer_id,md5(i#>>'{customer_snapshot,hotel_name}')::uuid hotel_id,i#>>'{customer_snapshot,hotel_name}' hotel_name,i->>'invoice_id' invoice_id,service::public.service_line service_line,date_trunc('month',(i->>'billing_period_start')::date)::date billing_period,coalesce(i->>'customer_segment',CASE WHEN n=1 THEN 'NEW' ELSE 'EXISTING' END)::public.customer_segment customer_segment,CASE WHEN nullif(contract->>'orm_team_id','') IS NOT NULL THEN md5(contract->>'orm_team_id')::uuid END orm_team_id,CASE WHEN nullif(contract->>'marcom_member_id','') IS NOT NULL THEN md5(contract->>'marcom_member_id')::uuid END marcom_member_id,base*CASE WHEN coalesce((i#>>'{totals,subtotal}')::numeric,0)>0 THEN (i#>>'{totals,total}')::numeric/(i#>>'{totals,subtotal}')::numeric ELSE 1 END amount,coalesce((i->>'paid_amount')::numeric,CASE WHEN i->>'status'='paid' THEN (i#>>'{totals,total}')::numeric ELSE 0 END)*CASE WHEN coalesce((i#>>'{totals,subtotal}')::numeric,0)>0 THEN base/(i#>>'{totals,subtotal}')::numeric ELSE 0 END paid_amount,i->>'status' status,coalesce((i->>'due_date')::date,date_trunc('month',(i->>'billing_period_start')::date)::date+14) due_date,i#>>'{customer_snapshot,customer_id}' original_customer_id,coalesce((SELECT e->>'event_type' FROM jsonb_array_elements(coalesce(payload->'collectionEvents','[]')) WITH ORDINALITY q(e,seq) WHERE e->>'customer_id'=i#>>'{customer_snapshot,customer_id}' ORDER BY seq LIMIT 1),'NORMAL') collection_status FROM expanded;
GRANT SELECT ON public.ac_canonical_invoice_rows TO service_role;
REVOKE ALL ON public.ac_canonical_invoice_rows FROM anon,authenticated;
CREATE OR REPLACE VIEW public.v_ac_debtors WITH(security_invoker=true) AS SELECT DISTINCT customer_id,service_line,billing_period,orm_team_id,marcom_member_id FROM public.ac_canonical_invoice_rows WHERE status NOT IN ('draft','void','written_off');
CREATE OR REPLACE VIEW public.v_ac_invoices_breakdown WITH(security_invoker=true) AS SELECT billing_period,customer_segment,service_line,orm_team_id,marcom_member_id,count(*) invoice_count FROM public.ac_canonical_invoice_rows WHERE status NOT IN ('draft','void') GROUP BY 1,2,3,4,5;
CREATE OR REPLACE VIEW public.v_ac_invoice_ranking WITH(security_invoker=true) AS WITH totals AS(SELECT billing_period,hotel_id,service_line,orm_team_id,marcom_member_id,sum(amount) amount FROM public.ac_canonical_invoice_rows WHERE status NOT IN ('draft','void','written_off') GROUP BY 1,2,3,4,5),r AS(SELECT *,dense_rank() OVER(PARTITION BY billing_period,service_line ORDER BY amount DESC) rank FROM totals) SELECT r.*,p.rank previous_month_rank,avg(r.rank) OVER(PARTITION BY r.hotel_id,r.service_line,r.orm_team_id,r.marcom_member_id) lifetime_average_rank FROM r LEFT JOIN r p ON p.hotel_id=r.hotel_id AND p.service_line=r.service_line AND p.billing_period=(r.billing_period-interval '1 month')::date AND p.orm_team_id IS NOT DISTINCT FROM r.orm_team_id AND p.marcom_member_id IS NOT DISTINCT FROM r.marcom_member_id;
CREATE OR REPLACE VIEW public.v_ac_grade_distribution WITH(security_invoker=true) AS SELECT (g->>'billing_period')::date billing_period,(g->>'grade')::public.payment_grade grade,i.service_line,i.orm_team_id,i.marcom_member_id,count(DISTINCT i.customer_id) customer_count FROM public.crm_documents d CROSS JOIN LATERAL jsonb_array_elements(coalesce(d.payload->'gradeRecords','[]')) g JOIN public.ac_canonical_invoice_rows i ON i.original_customer_id=g->>'customer_id' AND i.billing_period=(g->>'billing_period')::date WHERE d.namespace='crm' AND i.status NOT IN ('draft','void','written_off') GROUP BY 1,2,3,4,5;
CREATE OR REPLACE VIEW public.v_ac_overdue WITH(security_invoker=true) AS SELECT billing_period,service_line,orm_team_id,marcom_member_id,count(DISTINCT customer_id) customer_count,count(*) invoice_count,sum(greatest(amount-paid_amount,0)) outstanding FROM public.ac_canonical_invoice_rows WHERE status NOT IN ('draft','void','paid','written_off') AND due_date<(now() AT TIME ZONE 'Asia/Bangkok')::date AND amount>paid_amount GROUP BY 1,2,3,4;
CREATE OR REPLACE VIEW public.v_ac_suspended WITH(security_invoker=true) AS SELECT billing_period,service_line,orm_team_id,marcom_member_id,count(DISTINCT customer_id) customer_count FROM public.ac_canonical_invoice_rows WHERE collection_status='SUSPENDED' GROUP BY 1,2,3,4;
CREATE OR REPLACE VIEW public.v_ac_legal WITH(security_invoker=true) AS SELECT billing_period,service_line,orm_team_id,marcom_member_id,count(DISTINCT customer_id) customer_count FROM public.ac_canonical_invoice_rows WHERE collection_status='LEGAL' GROUP BY 1,2,3,4;
CREATE OR REPLACE VIEW public.v_ac_system_fee WITH(security_invoker=true) AS SELECT md5(h->>'id')::uuid hotel_id,h->>'name' hotel_name,NULL::uuid customer_id,make_date(y.year::int,p.ord::int,1) billing_period,'ORM'::public.service_line service_line,coalesce(nullif(h#>>'{system,monthlyCost}',''),'0')::numeric(12,2) amount,'monthly'::text cadence,p.status='"paid"'::jsonb paid,NULL::uuid orm_team_id,NULL::uuid marcom_member_id FROM public.crm_documents d CROSS JOIN LATERAL jsonb_array_elements(coalesce(d.payload->'hotels','[]')) h CROSS JOIN LATERAL jsonb_each(coalesce(h#>'{system,payments}','{}')) y(year,months) CROSS JOIN LATERAL jsonb_array_elements(y.months) WITH ORDINALITY p(status,ord) WHERE d.namespace='hotels' AND h#>>'{system,hplusPays}'='true';
REVOKE ALL ON public.v_ac_debtors,public.v_ac_invoices_breakdown,public.v_ac_invoice_ranking,public.v_ac_grade_distribution,public.v_ac_overdue,public.v_ac_suspended,public.v_ac_legal,public.v_ac_system_fee FROM anon,authenticated;
GRANT SELECT ON public.v_ac_debtors,public.v_ac_invoices_breakdown,public.v_ac_invoice_ranking,public.v_ac_grade_distribution,public.v_ac_overdue,public.v_ac_suspended,public.v_ac_legal,public.v_ac_system_fee TO service_role;
COMMENT ON VIEW public.ac_canonical_invoice_rows IS 'Original CRM accounting projection; deterministic UUID hashes retain the existing report interfaces without duplicate ledger records.';